create table states(id text primary key,name text not null,abbreviation text not null,country text not null default 'US',unique(country,abbreviation));
create table cities(id text primary key,name text not null,state_id text not null references states(id),time_zone text not null,center_lat double precision,center_lng double precision,active boolean not null default false,unique(state_id,name));
create table neighborhoods(id text primary key,city_id text not null references cities(id),name text not null,borough text,boundary jsonb,unique(city_id,name));
create table breweries(id text primary key,name text not null,slug text not null unique,website text not null,logo_url text,description text,classification text,verification_status text not null,source_url text not null,verified_at timestamptz);
create table brewery_locations(id text primary key,brewery_id text not null references breweries(id),name text not null,slug text not null unique,address text,city_id text not null references cities(id),state_id text not null references states(id),postal_code text,neighborhood_id text references neighborhoods(id),borough text,lat double precision check(lat between -90 and 90),lng double precision check(lng between -180 and 180),phone text,website text,opening_hours jsonb,time_zone text not null,amenities jsonb not null default '{}',image_url text,visit_status text not null,visitable boolean not null default false,verified_at timestamptz,source_url text not null,record jsonb not null);
create index locations_city_idx on brewery_locations(city_id,visitable);
create table sources(id text primary key,location_id text not null references brewery_locations(id),url text not null,reliability text not null,adapter text not null,unique(location_id,url));
create table beers(id text primary key,name text not null,producer_id text references breweries(id),original_style text,style_family text,abv numeric check(abv between 0 and 40),ibu numeric,description text,source_url text not null);
create index beers_style_idx on beers(style_family);
create table tap_snapshots(id text primary key,location_id text not null references brewery_locations(id),source_id text not null references sources(id),collected_at timestamptz not null,last_successful_verification timestamptz,parser_version text not null,checksum text not null,status text not null,entry_count integer not null,error text,unique(source_id,collected_at));
create index snapshots_location_time_idx on tap_snapshots(location_id,collected_at desc);
create table tap_entries(id text primary key,location_id text not null references brewery_locations(id),beer_id text not null references beers(id),serving_format text not null check(serving_format in ('draft','can','bottle','takeaway')),pour_size text,price text,availability text not null,source_url text not null,observed_at timestamptz not null,snapshot_id text not null references tap_snapshots(id),unique(snapshot_id,beer_id,serving_format));
create index entries_location_idx on tap_entries(location_id,snapshot_id);
create table trails(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 80),city_id text not null references cities(id),travel_mode text not null check(travel_mode in ('walking','driving','cycling','transit')),start_time text not null,planned_date date not null,estimated_duration integer not null,share_token text not null unique check(length(share_token)>=32),payload jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table trail_stops(id uuid primary key default gen_random_uuid(),trail_id uuid not null references trails(id) on delete cascade,location_id text not null references brewery_locations(id),position integer not null,estimated_arrival timestamptz not null,estimated_departure timestamptz not null,visit_minutes integer not null,travel_estimate jsonb,notes text,unique(trail_id,position));
create index trail_stops_trail_idx on trail_stops(trail_id);
create table rate_limits(key text primary key,window_start timestamptz not null default now(),count integer not null default 1);
create table ingestion_runs(id text primary key,started_at timestamptz not null,finished_at timestamptz,status text not null,attempted integer not null,successful integer not null,failed integer not null,details jsonb not null);

alter table states enable row level security;
alter table cities enable row level security;
alter table neighborhoods enable row level security;
alter table breweries enable row level security;
alter table brewery_locations enable row level security;
alter table sources enable row level security;
alter table beers enable row level security;
alter table tap_snapshots enable row level security;
alter table tap_entries enable row level security;
alter table trails enable row level security;
alter table trail_stops enable row level security;
alter table rate_limits enable row level security;
alter table ingestion_runs enable row level security;
